		} else if tagValue == "yearly" {
			keepCount := 1
		} else {
			continue // skip unknown tag values
		}

		// Get the sorted list of snapshots by creation timestamp
		sortedSnapshots := make([]*ec2.Snapshot, 0, len(snapshots.Snapshots))
		for _, snap := range snapshots.Snapshots {
